      fulfilments: [{ method: "GET", path: "/v1/fulfilments" }, { method: "POST", path: "/v1/fulfilments" }, { method: "GET", path: "/v1/fulfilments/:fulfilmentId" }, { method: "POST", path: "/v1/fulfilments/:fulfilmentId/retry" }, { method: "POST", path: "/v1/offers/:offerId/freeze-collection" }],
